pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, _node_capacity_cpu: u32, _node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
    let cpu_norm = (node_residual_cpu as f64 - job_cpu as f64) / mean_cpu_residual;
    let ram_norm = (node_residual_ram as f64 - job_ram as f64) / mean_ram_residual;

    // Non-linear penalty for imbalance
    let imbalance_penalty = ((cpu_norm - ram_norm).abs() * 100.0).powi(2);

    // Lookahead packing bonus
    let lookahead_bonus = if next_job_cpu > node_residual_cpu || next_job_ram > node_residual_ram { 15.0 } else { 1.0 };

    // Time horizon-aware factor
    let time_horizon_factor = (step_index as f64 / total_jobs as f64).powi(2);

    // Fine-grained residual fitting bonus
    let residual_bonus = ((node_residual_cpu - job_cpu) * (node_residual_ram - job_ram)) as f64;

    // Lookahead anticipation bonus
    let lookahead_anticipation_bonus = if next_job_cpu < node_residual_cpu && next_job_ram < node_residual_ram { 5.0 } else { 1.0 };

    // Combined score with enhanced residual fitting and lookahead anticipation
    let combined_res_bonus = (residual_bonus * lookahead_anticipation_bonus).powi(2);
    let score = cpu_norm + ram_norm - imbalance_penalty * time_horizon_factor * lookahead_bonus + combined_res_bonus;
    score
}

