    let residual_ratio_cpu = (node_residual_cpu as f64) / mean_cpu_residual;
    let residual_ratio_ram = (node_residual_ram as f64) / mean_ram_residual;
    let dead_space_ratio_cpu = 1.0 - residual_ratio_cpu.powi(2);
    let dead_space_ratio_ram = 1.0 - residual_ratio_ram.powi(2);
    let space_penalty_cpu = if dead_space_ratio_cpu > 0.5 { dead_space_ratio_cpu * 75.0 } else { 0.0 };
    let space_penalty_ram = if dead_space_ratio_ram > 0.5 { dead_space_ratio_ram * 75.0 } else { 0.0 };

    // Combine fine-grained residual fitting with lookahead anticipation
    let combined_residual_bonus = (residual_ratio_cpu + residual_ratio_ram) / 2.0 * lookahead_bonus;

    let score = cpu_norm + ram_norm - imbalance_penalty * time_horizon_factor + combined_residual_bonus - space_penalty_cpu - space_penalty_ram;
    score
}
